// Explicit taxonomy rows from the mission are kept in this same registry.
// They are mechanism hypotheses, not separate implementations or proof of
// demand.  Grouping them here makes the ingestion complete without creating
// parallel databases or pretending that every variant deserves a build.
function taxonomyRows(category, buyer, rows, monetization, distribution, recurrence, risk) {
  return rows.map(([id, name, mechanism]) => [
    `taxonomy-${id}`, name, category, buyer, mechanism,
    monetization, distribution, recurrence, risk
  ]);
}

