function blueprintFor(id, name) {
  return {
    id: `commercial.thread.${id}.preflight`,
    version: '1.0.0',
    purpose: `Prepare a bounded local research and experiment packet for ${name}.`,
    inputs: ['opportunityId', 'publicEvidenceRefs', 'optionalCustomerAuthorizedRefs'],
    outputs: ['buyerHypothesis', 'mechanismMap', 'experimentPacket', 'killDecision'],
    eligibility: {
      requiredFields: ['opportunityId'],
      requiredEvidenceRefs: [],
      allowSyntheticFixtures: true
    },
    policy: {
      consequenceClass: 'LOCAL_PREPARATION',
      externalEffects: [],
      requiresOwner: false,
      purpose: 'Research and prepare an opportunity without external effects.'
    },
    evaluator: {
      type: 'DETERMINISTIC',
      requiredOutputs: ['buyerHypothesis', 'mechanismMap', 'experimentPacket', 'killDecision'],
      successConditions: [
        'Thread-derived claims remain labeled HYPOTHESIS.',
        'Unknown economic and platform state remains unresolved.',
        'The experiment has a measurable payment-oriented metric and a kill condition.'
      ],
      killConditions: [
        'No lawful evidence or customer-authorized evidence can be obtained.',
        'The lane requires unauthorized external action.',
        'The economic hypothesis fails the declared acceptance gate.'
      ]
    },
    retryStrategy: { maxAttempts: 2, backoffMs: 0, retryableErrors: [], nonRetryableErrors: [] },
    ownerBurden: { minutes: 5, reason: 'Owner review is required before external access, contact, spend, or publication.' },
    expiration: { maxAgeMs: 7 * 24 * 60 * 60 * 1000 },
    successConditions: ['Local packet is complete and reproducible.'],
    killConditions: [
      'No lawful evidence or customer-authorized evidence can be obtained.',
      'The lane requires unauthorized external action.',
      'The economic hypothesis fails the declared acceptance gate.'
    ]
  };
}

function makeOpportunity(definition, index) {
  const [id, name, category, buyer, mechanism, monetization, distribution, recurrence, risk] = definition;
  return {
    id,
    rank: 5 + index,
    name,
    category,
    verdict: 'RESEARCH_ONLY',
    origin: 'THREAD_EXPLICIT',
    buyerSegments: [buyer],
    mechanism,
    observedBuyerSignals: [],
    evidence: {
      classification: 'HYPOTHESIS',
      observedTraction: 'This lane was explicitly proposed in the UberBond thread; this registry contains no independent buyer, payment, or retention proof for it.',
      sources: [{ ...THREAD_SOURCE, lane: id }]
    },
    candidate: {
      id,
      name,
      category,
      buyer: { value: buyer, claimType: 'HYPOTHESIS' },
      monetization: { value: monetization, claimType: 'HYPOTHESIS' },
      timeToCashDays: { value: 'UNRESOLVED', claimType: 'UNRESOLVED' },
      acquisition: { value: distribution, claimType: 'HYPOTHESIS' },
      capital: { value: 'UNRESOLVED', claimType: 'UNRESOLVED' },
      platformDependency: { value: 'Requires current provider and policy verification', claimType: 'UNRESOLVED' },
      automationPotential: { value: 'Potentially high; must be measured', claimType: 'HYPOTHESIS' },
      founderBurden: { value: 'UNRESOLVED', claimType: 'UNRESOLVED' },
      recurringTrigger: { value: recurrence, claimType: 'HYPOTHESIS' },
      dataAsset: { value: 'Potentially compounding if rights and consent permit', claimType: 'HYPOTHESIS' },
      failureMode: { value: risk, claimType: 'HYPOTHESIS' }
    },
    priceHypotheses: [{ label: 'Initial bounded test', amountUsd: null, classification: 'HYPOTHESIS' }],
    deliverables: ['Evidence ledger', 'Mechanism map', 'Bounded experiment packet', 'Kill or promote recommendation'],
    exclusions: COMMON_EXCLUSIONS,
    constraints: COMMON_CONSTRAINTS,
    recurringRoute: recurrence,
    testCost: { lowUsd: null, highUsd: null, classification: 'UNRESOLVED' },
    firstRevenueWindowDays: { low: null, high: null, classification: 'UNRESOLVED' },
    competitiveRisk: risk,
    sevenDayExperiment: [
      'Write the buyer, payer, value, payment, fulfillment, and recurring hypotheses.',
      'Collect and classify permitted evidence; do not treat thread claims as market proof.',
      'Create deterministic synthetic fixtures for the core workflow and failure modes.',
      'Estimate delivery cost, owner minutes, platform dependency, and legal questions.',
      'Prepare one bounded offer and one measurable first-payment experiment.',
      'Define exact authority, route, payload, identity, time, budget, and kill conditions.',
      'Keep the lane at RESEARCH_ONLY until external evidence and owner approval exist.'
    ],
    taskBlueprint: blueprintFor(id, name)
  };
}

export const THREAD_OPPORTUNITY_UNIVERSE = Object.freeze(
  DEFINITIONS.map((definition, index) => makeOpportunity(definition, index))
);

export const THREAD_OPPORTUNITY_COUNT = THREAD_OPPORTUNITY_UNIVERSE.length;
